    createIpv6Order: {
        parameters: {
            query?: never;
            header?: {
                /** @description Unique key per purchase, 16–128 letters, digits or dashes (a UUID works). Send it here or as `idempotencyKey` in the body: one of the two is required (400 `IDEMPOTENCY_KEY_REQUIRED`), and the header wins when both are sent. The same request again with the same key never charges twice; the same key with another speed or term answers 409 `IDEMPOTENCY_CONFLICT`. */
                "Idempotency-Key"?: string;
            };
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                /**
                 * @example {
                 *       "speedMbps": 200,
                 *       "days": 7,
                 *       "idempotencyKey": "8f14e45f-ceea-4e7a-9b1d-3c2a5d6e7f80"
                 *     }
                 */
                "application/json": components["schemas"]["Ipv6Selection"] & {
                    /** @description Refuse the purchase if the total is above this amount (USD, up to 50,000): 409 `PRICE_CHANGED`, nothing is created or charged. */
                    maxTotal?: number;
                    /** @description Alternative to the `Idempotency-Key` header; the header wins when both are sent. 16 to 128 letters, digits or dashes (a UUID works). */
                    idempotencyKey?: string;
                };
            };
        };
        responses: {
            /** @description Replayed: this Idempotency-Key was already paid. The order it created, no new charge. Also answered, with that order, when an earlier paid order of yours for the same speed and term is still being delivered: a second one is never bought. `invoice` is present when the replay is detected at checkout; the order's own `invoice` always carries the payment status. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "type": "response",
                     *       "message": "This purchase was already received.",
                     *       "payload": {
                     *         "replayed": true,
                     *         "order": {
                     *           "id": "ord_7a1c",
                     *           "product": "ipv6-speed",
                     *           "status": "active",
                     *           "createdAt": "2026-10-20T09:00:00.000Z",
                     *           "speedMbps": 200,
                     *           "days": 7,
                     *           "planName": "IPv6 Unlimited · 200 Mbps · 7 days",
                     *           "trafficMetered": false,
                     *           "expiresAt": "2026-10-27T09:00:00.000Z",
                     *           "daysRemaining": 7,
                     *           "channel": "api",
                     *           "invoice": {
                     *             "id": "inv_3b9e",
                     *             "vat": 0,
                     *             "vatRate": 0,
                     *             "paid": true,
                     *             "status": "PAID",
                     *             "refunded": false
                     *           }
                     *         }
                     *       },
                     *       "pagination": {}
                     *     }
                     */
                    "application/json": components["schemas"]["Envelope"] & {
                        payload?: {
                            /** @constant */
                            replayed?: true;
                            order?: components["schemas"]["Ipv6Order"];
                            invoice?: components["schemas"]["Ipv6InvoiceSummary"];
                        };
                    };
                };
            };
            /** @description Delivered: the plan is active. `order` is the new order; `invoice` is its paid invoice (`id`, `subtotal`, `vat`, `vatRate`, `total`, `paid`). */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "type": "response",
                     *       "message": "Success",
                     *       "payload": {
                     *         "order": {
                     *           "id": "ord_7a1c",
                     *           "product": "ipv6-speed",
                     *           "status": "active",
                     *           "createdAt": "2026-10-20T09:00:00.000Z",
                     *           "speedMbps": 200,
                     *           "days": 7,
                     *           "planName": "IPv6 Unlimited · 200 Mbps · 7 days",
                     *           "trafficMetered": false,
                     *           "expiresAt": "2026-10-27T09:00:00.000Z",
                     *           "daysRemaining": 7,
                     *           "channel": "api",
                     *           "invoice": {
                     *             "id": "inv_3b9e",
                     *             "vat": 0,
                     *             "vatRate": 0,
                     *             "paid": true,
                     *             "status": "PAID",
                     *             "refunded": false
                     *           }
                     *         },
                     *         "invoice": {
                     *           "id": "inv_3b9e",
                     *           "vat": 0,
                     *           "vatRate": 0,
                     *           "paid": true
                     *         }
                     *       },
                     *       "pagination": {}
                     *     }
                     */
                    "application/json": components["schemas"]["Envelope"] & {
                        payload?: {
                            order?: components["schemas"]["Ipv6Order"];
                            invoice?: components["schemas"]["Ipv6InvoiceSummary"];
                        };
                    };
                };
            };
            /** @description `VALIDATION_ERROR`: the body is not a valid selection (`message` names the field and the rule it broke; unknown fields are refused), or the total is outside the invoice limits (`message` says which). `IDEMPOTENCY_KEY_REQUIRED`: no valid Idempotency-Key in the header or the body. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorEnvelope"];
                };
            };
            401: components["responses"]["Unauthorized"];
            402: components["responses"]["Ipv6PaymentRequired"];
            403: components["responses"]["Ipv6Forbidden"];
            409: components["responses"]["Ipv6Conflict"];
            422: components["responses"]["Ipv6NotDelivered"];
            /** @description `RATE_LIMITED`: 20 purchase requests an hour per account; `retryAfter` and `Retry-After` give the seconds to wait. `TOO_MANY_UNPAID_INVOICES`: ten or more unpaid invoices on the account in the last 24 hours (any product): pay one, wait for them to expire, or contact support. An answer without `payload.code` is the hourly window of the API key (see Rate limits and tiers). */
            429: {
                headers: {
                    "X-RateLimit-Limit": components["headers"]["X-RateLimit-Limit"];
                    "X-RateLimit-Remaining": components["headers"]["X-RateLimit-Remaining"];
                    "X-RateLimit-Reset": components["headers"]["X-RateLimit-Reset"];
                    "Retry-After": components["headers"]["Retry-After"];
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorEnvelope"];
                };
            };
            503: components["responses"]["Ipv6Unavailable"];
        };
    };
